  async loadDxf(file){if(!file)return;const token={};this.cadLoad=token;try{if(file.size>8*1024*1024)throw new Error('DXF 最多 8 MB。');const data=readDxf(await file.text());if(this.destroyed||this.cadLoad!==token)return;if(!data.layers.length)throw new Error('未找到封閉 LWPOLYLINE；請先在 CAD 中整理房間輪廓。');this.cadSource=data;this.control('cad-layer').setItems(data.layers.map(value=>({value,label:value})));this.control('cad-layer').setValue(data.layers.includes('ROOMS')?'ROOMS':data.layers[0]);this.message('DXF 已讀取；選擇圖層與單位後，按匯入建立新設計。只重建封閉房間輪廓。');}catch(e){this.message(e.message);}}
