  async loadMaterialImage(file){if(!file)return;const id=this.control('material-slot').getValue(),channel=this.control('material-channel').getValue(),tileMetres=this.control('material-tile').getValue(),token={};this.materialLoad=token;try{if(file.size>8*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('貼圖限 8 MB 的 PNG／JPEG／WebP。');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('貼圖讀取失敗。'));reader.readAsDataURL(file);});const entries=await decodeMaterialPack({format:'lumiere-materials',version:2,materials:[{id,data,tileMetres,channel}]});if(this.destroyed||this.materialLoad!==token){entries.forEach(m=>m.image.close());return;}const view=this.views.find(v=>v.renderer),materials=[...(view.materialEntries||[]).filter(m=>m.id!==id||m.channel!==channel),...entries].map(({id,data,tileMetres,channel})=>({id,data,tileMetres,channel}));try{validateMaterialPack({format:'lumiere-materials',version:2,materials});}catch(e){entries.forEach(m=>m.image.close());throw e;}view.setMaterials(entries,true);this.message('已套用自訂貼圖；請另存材質包，下次可重新載入。');}catch(e){this.message(e.message);}}
