  saveDraft(){try{const text=this.store.serialize();localStorage.setItem(STORAGE_KEY,text);this.saved=text;this.sync();this.message('已儲存建築草稿；素材、底圖、IFC 與圖紙請用「另存完整專案」一起保存。');}catch{this.message('此瀏覽器無法儲存草稿，請使用匯出 JSON。');}}
  loadDraft(){try{const text=localStorage.getItem(STORAGE_KEY);if(!text)throw new Error('尚未儲存草稿。');this.clearUnderlays();this.editPrefs.clear();this.multiIds=[];const next=parseProject(text);this.captureContext=null;this.store.replace(next);this.saved=this.store.serialize();this.selection=null;this.sync();this.views.forEach(v=>v.fit());this.message('已載入草稿；原設計仍可復原。');}catch(error){this.message(error.message);}}
  async importFiles(files){
    const file=files?.[0];if(!file)return;const revision=this.store.revision;
    try{if(file.size>LIMITS.fileBytes)throw new Error('設計檔最多 10 MB。');const text=await file.text();if(this.destroyed)return;if(this.store.revision!==revision)throw new Error('讀檔期間設計已變更，請重新開啟檔案。');const project=parseProject(text);this.clearUnderlays();this.editPrefs.clear();this.multiIds=[];this.captureContext=null;this.store.replace(project);this.saved=this.store.serialize();this.selection=null;this.sync();this.views.forEach(v=>v.fit());this.message('本機 JSON 已開啟，沒有上傳到伺服器。');}catch(error){if(!this.destroyed)this.message(`讀取失敗：${error.message}`);}
  }
  exportFile(){
    const text=this.store.serialize(),blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='lumiere-design.json';document.body.appendChild(anchor);anchor.click();anchor.remove();
    const timer=setTimeout(()=>{URL.revokeObjectURL(url);this.urls.delete(url);},30000);this.urls.set(url,timer);this.message('已匯出設計 JSON，請查看下載項目。');
  }
  destroy(){if(this.destroyed)return;this.destroyed=true;this.reference.destroy();this.projectBundle.destroy();this.ifcAbort?.abort();this.leaveModal?.destroy();this.underlays.forEach(u=>u.image.close());this.underlays.clear();this.unsubscribe?.();this.listeners.forEach(fn=>fn());this.urls.forEach((timer,url)=>{clearTimeout(timer);URL.revokeObjectURL(url);});this.urls.clear();this.pageRenderer?.destroy();}
